const toast=(s)=>{let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',5000)};document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.demo)));document.querySelector('#request-form')?.addEventListener('submit',e=>{e.preventDefault();let v=document.querySelector('#amount').value.trim();let err=document.querySelector('#form-error');if(!/^\d+(\.\d{1,2})?$/.test(v)||Number(v)<=0||Number(v)>64){err.textContent='Enter a positive amount with at most two decimal places, no greater than $64.00.';err.style.display='block';return;}document.querySelector('#refund-form').style.display='none';document.querySelector('#confirmation').style.display='block';});document.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>{let s=document.querySelector('#decision-note').value.trim();if(!s){toast('Add a decision reason before continuing.');document.querySelector('#decision-note').focus();return;}if(confirm('Record this '+b.dataset.decision+' decision? This is a simulated prototype action.'))toast('Decision recorded in this prototype only. No refund executed.');}));document.querySelector('#revoke')?.addEventListener('click',()=>{if(confirm('Revoke agent refund authority? Pending consequential actions must be blocked.')){document.querySelector('#authority-result').innerHTML='<div class="notice red"><strong>Authority revoked.</strong><br>Refund processing is blocked in this prototype state.</div>';toast('Prototype state changed. No live agent is connected.');}});